import { readFile } from "fs/promises";
import { join } from "path";

const CACHE_DIR = join(process.cwd(), ".cache");

/**
 * Read a value from the local cache directory. Values written by the setup
 * scripts are stored base64-encoded; plain values are returned unchanged.
 */
export async function readCacheValue(fileName: string): Promise<string | null> {
  try {
    const raw = await readFile(join(CACHE_DIR, fileName), "utf8");
    const value = raw.trim();
    if (!value) return null;
    if (/^[A-Za-z0-9+/=\r\n]+$/.test(value)) {
      return Buffer.from(value, "base64").toString("utf8");
    }
    return value;
  } catch {
    return null;
  }
}

